<?php
require_once dirname(__DIR__).'/app/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect(app_path('index.php'));verify_csrf();$id=(int)($_POST['listing_id']??0);$name=trim((string)($_POST['sender_name']??''));$email=trim((string)($_POST['sender_email']??''));$phone=trim((string)($_POST['sender_phone']??''));$message=trim((string)($_POST['message']??''));$s=db()->prepare("SELECT slug,name,owner_user_id FROM listings WHERE id=:id AND status='published'");$s->execute([':id'=>$id]);$listing=$s->fetch();$slug=$listing['slug']??'';if(!$slug||$name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||text_len($message)<15||text_len($message)>2000){flash('error','Please check your enquiry details and try again.');redirect($slug?app_path('index.php?listing='.rawurlencode((string)$slug)):app_path('index.php'));}db()->prepare('INSERT INTO enquiries(listing_id,user_id,sender_name,sender_email,sender_phone,message) VALUES(:l,:u,:n,:e,:p,:m)')->execute([':l'=>$id,':u'=>current_user_id()?:null,':n'=>text_substr($name,0,80),':e'=>$email,':p'=>text_substr($phone,0,30),':m'=>$message]);if((int)($listing['owner_user_id']??0)>0){notify_user((int)$listing['owner_user_id'],'New business enquiry','A visitor sent a new enquiry for '.(string)$listing['name'].'.','owner/inbox.php');notify_owner_of_inquiry((int)$id,$name,$email,'Enquiry',$message);}flash('success','Your enquiry has been sent to the guide inbox for this listing.');redirect(app_path('index.php?listing='.rawurlencode((string)$slug)));
